// HasChatSessionsWith applies the HasEdge predicate on the "chat_sessions" edge with a given conditions (other predicates).
func HasChatSessionsWith(preds ...predicate.ChatSession) predicate.Lead {
	return predicate.Lead(func(s *sql.Selector) {
		step := newChatSessionsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasScheduledMeetings applies the HasEdge predicate on the "scheduled_meetings" edge.
func HasScheduledMeetings() predicate.Lead {
	return predicate.Lead(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ScheduledMeetingsTable, ScheduledMeetingsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasScheduledMeetingsWith applies the HasEdge predicate on the "scheduled_meetings" edge with a given conditions (other predicates).
func HasScheduledMeetingsWith(preds ...predicate.ScheduledMeeting) predicate.Lead {
	return predicate.Lead(func(s *sql.Selector) {
		step := newScheduledMeetingsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Lead) predicate.Lead {
	return predicate.Lead(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Lead) predicate.Lead {
	return predicate.Lead(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Lead) predicate.Lead {
	return predicate.Lead(sql.NotPredicates(p))
}
